# Adding tanks: one place, section required, names made in the standard form; tanks without a section fixed in one click.
import os; os.environ['E2E_PORT'] = '8858'
from harness import *
with sync_playwright() as p:
    BROWSER = p.chromium.launch(); harness_browser[0] = BROWSER
    sb = MockSB(); sb.add_user('admin@example.com', 'admin123', role='admin', uid='u-admin')
    ctx, pg = new_page(p, sb); login(pg, 'admin@example.com', 'admin123'); pg.wait_for_function('() => !!window._cloudSyncDone', timeout=10000)
    pg.evaluate("show('farm-setup')"); pg.wait_for_timeout(400)
    check('A1 Farm setup has one "➕ Add tanks" card with a required section', pg.evaluate("!!document.getElementById('ta-farm') && !!document.getElementById('ta-sec') && !document.getElementById('mu-unit')"))
    pg.select_option('#ta-farm', '__new'); pg.fill('#ta-newcode', 'f3'); pg.fill('#ta-newname', 'Nursery'); pg.fill('#ta-n', '4'); pg.wait_for_timeout(100)
    pv = pg.inner_text('#ta-preview')
    check('A2 a new farm: section 1 suggested, names shown before saving (F3.S01T01 … F3.S01T04)', pg.input_value('#ta-sec') == '1' and 'F3.S01T01' in pv and 'F3.S01T04' in pv, pv)
    pg.click('#ta-save'); pg.wait_for_timeout(700)
    us = pg.evaluate("RAW.filter(u=>u.farm==='F3').map(u=>[u.unit,u.section,u.fishNo])")
    check('A3 saved: 4 empty tanks in F3.S01, the farm registered as "Nursery"', us == [[f'F3.S01T0{i}', 'F3.S01', 0] for i in range(1, 5)] and pg.evaluate("getFarmsRegistry().F3") == 'Nursery', us)
    check('A4 they reach the cloud like every tank', all(any(f'F3.S01T0{i}' in str(k) for k in sb.upserts.get('farm_units', {})) for i in range(1, 5)) if 'farm_units' in getattr(sb, 'upserts', {}) else True)
    pg.evaluate("show('farm-setup',true)"); pg.wait_for_timeout(300)
    pg.select_option('#ta-farm', 'F3'); pg.wait_for_timeout(100)
    check('A5 an existing farm: its sections shown, the NEXT section suggested', pg.input_value('#ta-sec') == '2' and 'S01 (4)' in pg.inner_text('#ta-secinfo'), (pg.input_value('#ta-sec'), pg.inner_text('#ta-secinfo')))
    pg.fill('#ta-sec', '1'); pg.dispatch_event('#ta-sec', 'input'); pg.wait_for_timeout(100)
    check('A6 same section: the next free tank number suggested (5)', pg.input_value('#ta-t0') == '5')
    pg.fill('#ta-t0', '3'); pg.fill('#ta-n', '4'); pg.dispatch_event('#ta-n', 'input'); pg.wait_for_timeout(100)
    pv = pg.inner_text('#ta-preview')
    check('A7 names that already exist are listed and skipped', 'F3.S01T03' in pv and 'F3.S01T04' in pv and 'موجودين' in pv and 'هيتضاف 2' in pv, pv)
    pg.check('#ta-hasfish'); pg.fill('#ta-fish', '5000'); pg.fill('#ta-wt', '0.8'); pg.click('#ta-save'); pg.wait_for_timeout(600)
    check('A8 with fish: count, weight and stock date saved', pg.evaluate("RAW.filter(u=>u.unit==='F3.S01T05'||u.unit==='F3.S01T06').map(u=>u.fishNo+'/'+u.startWt)") == ['5000/0.8', '5000/0.8'])
    pg.evaluate("window._fs={farm:'F3'}; show('feed-sheet')"); pg.wait_for_timeout(400)
    check('A9 the feed sheet lists the new tanks (empty ones locked, stocked ones open)', pg.evaluate("window._fs.rows.length") == 6 and pg.evaluate("window._fs.rows.filter(r=>r.fish>0).length") == 2)
    # old tanks without a section (as added before from Settings)
    pg.evaluate("() => { const u=getFarmUnits(); ['N1','N2'].forEach((n,i)=>u.push({id:'x'+i,name:n,unitType:'tank',volume:2,fishNo:1000,startWt:1,farm:'F3'})); saveFarmUnits(u); }")
    pg.evaluate("show('settings'); settingsTab='units'; show('settings',true)"); pg.wait_for_timeout(300)
    pg.evaluate("settingsAddUnitRow()"); pg.wait_for_timeout(400)
    check('A10 Settings\' "new tank" opens the one place to add tanks', pg.evaluate("currentView") == 'farm-setup' and pg.evaluate("!!document.getElementById('ta-save')"))
    check('A11 tanks without a section are listed with a fix', pg.evaluate("!!document.getElementById('ta-fix')") and 'N1' in pg.inner_text('#ta-fix'))
    pg.fill('#ta-fix-F3', '2'); pg.click('#ta-fix button'); pg.wait_for_timeout(500)
    check('A12 one click puts them in the chosen section, names kept', pg.evaluate("getFarmUnits().filter(u=>u.name==='N1'||u.name==='N2').map(u=>u.section)") == ['F3.S02', 'F3.S02'] and not pg.evaluate("!!document.getElementById('ta-fix')"))
    pg.evaluate("window._fs={farm:'F3'}; show('feed-sheet',true)"); pg.wait_for_timeout(300)
    check('A13 the feed sheet now shows them in section 2', sorted(pg.evaluate("window._fs.rows.filter(r=>r.unit[0]==='N').map(r=>r.no.s+':'+r.no.label)")) == ['2:N1', '2:N2'])
    check('A14 no page errors', not pg._errs, pg._errs)
    ctx.close()
    fails = [r for r in RESULTS if not r[1]]
    for nm, ok, dt in RESULTS: print(('✅ ' if ok else '❌ ') + nm + ('' if ok else f'  → {str(dt)[:300]}'))
    print(f'\n{len(RESULTS)-len(fails)}/{len(RESULTS)} passed')
